Let $A \in C^\infty(\mathbb{R})$ be admissible. 
Let $f \in \mathcal{D}'(\mathbb{R})$ be supported in $(0,\infty)$. 
Then, 

  \begin{equation}
  \langle \Lambda_{ND} (f), \phi \rangle =    \langle f , \tilde\Lambda_{ND} ( \phi )  \rangle, 
  \end{equation}
   {for all   $\phi \in C_c^\infty(\mathbb{R})$.}

Let $u$ satisfy 
  \begin{align}
    \square_A u &= 0, && x>0,\, t\in\mathbb{R},\\
    \partial_x u (0,t) &= \phi(t), && t\in\mathbb{R},\\
    u(x,t) &= 0, && x>0,\, t<0.
  \end{align}
  where $\phi \in C^{\infty}_c (\mathbb{R})$ is supported in $(0,\infty)$. Assume furthermore that $A(x)=A_\infty$ for $x > \ell$. Then
  \begin{equation}
    \big|  u(0,t) -c(t)  \big|^2 \leq \int_0^{\ell} \left(   \partial_x u (x,t) + \frac{A(x)}{A_\infty} \partial_t u(x,t) \right)^2  \,\mathrm{d}x.  
  \end{equation}
  where
  \begin{equation}
    c(t) = - \frac{1}{A_\infty} \int_0^t \phi (t) \,\mathrm{d}t.
  \end{equation}

Let $M = \max \left\lvert A^{-1} \partial_x A \right\rvert$ and $\lambda = \tfrac{M}{2} e^{-M \ell} \sqrt{1 - 2 M \ell e^{-2 M \ell}}$ where $\ell$ is the length of the domain of interest defined along with $\mathscr{E}_{\phi,g_1,g_2}$ in (A.1). Set
  \begin{align}
    g_1(x) = \frac{e^{\frac{M}{2} x}}{\sqrt{\lambda^2 + \left\lparen M/2 \right\rparen^2}}
    \Bigg(& \sqrt{\lambda^2 + \left\lparen M/2 \right\rparen^2} \cosh \left\lparen \sqrt{\lambda^2 + \left\lparen M/2 \right\rparen^2} x \right\rparen \\
          & + \left\lparen \lambda - M/2 \right\rparen \sinh \left\lparen \sqrt{\lambda^2 + \left\lparen M/2 \right\rparen^2} x \right\rparen \Bigg)
  \end{align}
  \begin{align}
    g_2(x) = \frac{e^{\frac{M}{2} x}}{\sqrt{\lambda^2 + \left\lparen M/2 \right\rparen^2}}
    \Bigg(& \sqrt{\lambda^2 + \left\lparen M/2 \right\rparen^2} \cosh \left\lparen \sqrt{\lambda^2 + \left\lparen M/2 \right\rparen^2} x \right\rparen \\
          & - \left\lparen \lambda + M/2 \right\rparen \sinh \left\lparen \sqrt{\lambda^2 + \left\lparen M/2 \right\rparen^2} x \right\rparen \Bigg)
  \end{align}
  Then $g_1$ and $g_2$ are strictly 
  positive on $[0,\ell]$, and they satisfy (A.6) and (A.7). 
  As a consequence, (A.8) holds for $\tau >  \tau_0:= \max \operatorname{supp}  \phi $ and hence
    \begin{equation}

    \mathscr{E}_{\phi,g_1,g_2}(\tau) \leq \mathscr{E}_{\phi,g_1,g_2}(\tau_0) e^{-\lambda (\tau-\tau_0)}
  \end{equation}
  by Gr\"onwall's inequality.
